var eliteX=ox+IEE.x*sc, eliteY=oy+IEE.y*sc;
ctx.beginPath(); ctx.moveTo(eliteX,eliteY-5*_MZ); ctx.lineTo(eliteX+4.5*_MZ,eliteY+4*_MZ); ctx.lineTo(eliteX-4.5*_MZ,eliteY+4*_MZ); ctx.closePath(); ctx.fill();
